class Task:
    def __init__(self, C, D, T, J):
        self.C = C
        self.D = D
        self.T = T
        self.J = J

def count_jobs(task, t):
    val = floor((t + task.J - task.D) / task.T) + 1
    return max(0, val)

def compute_release_interference(task, t, overheads):
    num_releases = ceil((t + task.J) / task.T)
    return num_releases * (overheads['RelO'] + overheads['TsetO'])

def compute_blocking(t, task_set, overheads):
    if t >= max(task.D for task in task_set):
        return 0
    return max(overheads['IpB'], overheads['SchedO'] + overheads['TsetO'])
